'use server'

import { revalidatePath } from 'next/cache'
import { cookies } from 'next/headers'

export async function getNotificationPreference() {
  const cookieStore = await cookies()
  return cookieStore.get('notifications')?.value === 'on'
}

export async function toggleNotificationPreference(currentPath: string) {
  const cookieStore = await cookies()
  const current = cookieStore.get('notifications')?.value

  cookieStore.set('notifications', current === 'on' ? 'off' : 'on', {
    path: '/',
    httpOnly: true,
    sameSite: 'lax',
  })

  revalidatePath(currentPath)
}

'use client'

import { useCallback, useTransition } from 'react'

interface ToggleFormProps {
  currentPath: string
  enabled: boolean
  action: (formData: FormData) => void
}

export function ToggleForm({ currentPath, enabled, action }: ToggleFormProps) {
  const [isPending, startTransition] = useTransition()

  const handleChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const formData = new FormData()
      formData.set('path', currentPath)
      startTransition(() => {
        action(formData)
      })
    },
    [currentPath, action],
  )

  return (
    <form>
      <label>
        <input
          type="checkbox"
          name="notifications"
          defaultChecked={enabled}
          disabled={isPending}
          onChange={handleChange}
        />
        Enable Notifications
      </label>
      {isPending && <span> Updating...</span>}
    </form>
  )
}

import { getNotificationPreference, toggleNotificationPreference } from './actions'
import { ToggleForm } from './toggle-form'

interface SettingsPageProps {
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>
}

export default async function SettingsPage({}: SettingsPageProps) {
  const enabled = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <p>Notification Preferences</p>
      <p>
        Notifications are currently <strong>{enabled ? 'ON' : 'OFF'}</strong>.
      </p>
      <ToggleForm
        currentPath="/"
        enabled={enabled}
        action={toggleNotificationPreference.bind(null, '/')}
      />
    </main>
  )
}

import type { Metadata } from 'next'

export const metadata: Metadata = {
  title: 'Settings',
}

export default function RootLayout({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}

